import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"作战区","description":"","frontmatter":{},"headers":[],"relativePath":"lab/index.md","filePath":"lab/index.md","lastUpdated":1787456457000}'),o={name:"lab/index.md"};function s(c,t,l,n,h,i){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="作战区" tabindex="-1">作战区 <a class="header-anchor" href="#作战区" aria-label="Permalink to &quot;作战区&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">这个板块完全公开，且没有任何技术兜底</p><p>这里放<strong>真实客户项目的进行中记录</strong>。它和站点其他板块一样会发布到线上，也会留在 GitHub 提交历史里——<strong>删得掉页面，删不掉历史</strong>。</p><p>曾经存在过「dev 可见 / build 排除 / git 排除」的三层隔离，<strong>已于 2026-08-06 全部移除</strong>（经过见 <code>specs/2026-08-05-lab-module-design.md</code>）。这意味着：<strong>提交即公开，推送即上线，写进去就撤不回。</strong></p><p>所以下面这张表是唯一的控制点，写之前过一遍：</p><table tabindex="0"><thead><tr><th>不写</th><th>原因</th></tr></thead><tbody><tr><td>客户明确要求保密的信息</td><td>保密义务</td></tr><tr><td>未公开的价格条款、合同细节</td><td>商业敏感</td></tr><tr><td>第三方提供的未授权素材</td><td>版权</td></tr><tr><td>对客户沟通行为的负面评价</td><td>客户会看到</td></tr><tr><td><strong>拿不准的</strong></td><td><strong>拿不准本身就是不写的理由</strong></td></tr></tbody></table></div><h2 id="和其他板块的区别" tabindex="-1">和其他板块的区别 <a class="header-anchor" href="#和其他板块的区别" aria-label="Permalink to &quot;和其他板块的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>回答什么</th><th>什么时候写</th></tr></thead><tbody><tr><td><a href="/method/">方法论</a> <a href="/prompts/">Prompt 库</a> <a href="/tools/">工具地图</a></td><td>该怎么做</td><td>事后提炼</td></tr><tr><td><a href="/pipelines/">实战流水线</a></td><td>这套工具组合怎么跑</td><td>事后提炼</td></tr><tr><td><a href="/cases/">案例拆解</a></td><td>别人 / 演示项目怎么做的</td><td>事后复盘</td></tr><tr><td><strong>作战区</strong></td><td><strong>这个项目做到哪了、下一步做什么</strong></td><td><strong>进行中，边做边写</strong></td></tr></tbody></table><p><strong>这里的文件是工作产物本身，不是记录。</strong> <code>01-proposal.md</code> 就是要发给客户的那份提案，写完直接用，不是「提案的总结」。</p><h2 id="项目看板" tabindex="-1">项目看板 <a class="header-anchor" href="#项目看板" aria-label="Permalink to &quot;项目看板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>阶段</th><th>卡在哪</th></tr></thead><tbody><tr><td><a href="/lab/shuangyu-fries/">双宇食品 · 薯条脆</a></td><td>4 · A 片 v2 待生成</td><td>客户要求补足真空、低温、油炸、脱水、脱脂的完整工艺链；温度参数与离心脱油工序仍待书面确认</td></tr></tbody></table><h2 id="阶段与放行条件" tabindex="-1">阶段与放行条件 <a class="header-anchor" href="#阶段与放行条件" aria-label="Permalink to &quot;阶段与放行条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>产出</th><th>放行条件</th></tr></thead><tbody><tr><td>0 · 立项</td><td><code>00-brief</code></td><td>已知与未知划分清楚，风险列出</td></tr><tr><td>1 · 提案</td><td><code>01-proposal</code> <code>02-materials</code></td><td>内部讨论通过</td></tr><tr><td>2 · 对客</td><td>反馈写回 <code>00-brief</code></td><td>方向确认、物料到位</td></tr><tr><td>3 · 分镜</td><td><code>03-storyboard</code></td><td>逐镜标注可生成性</td></tr><tr><td>4 · Prompt</td><td><code>04-prompts</code></td><td>按工具分组，不可生成的标出替代方案</td></tr><tr><td>5 · 生成</td><td><code>05-genlog</code></td><td>全片跑通一版再抠单镜</td></tr><tr><td>6 · 后期交付</td><td>成片</td><td>——</td></tr><tr><td>7 · 复盘</td><td><code>06-review</code></td><td>交付后立刻写</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">阶段 1 没放行，不要写分镜和 Prompt</p><p>提案方向一变，分镜全废。这是这类项目里最容易发生的浪费。</p></div><div class="tip custom-block"><p class="custom-block-title">最容易被跳过、也最值钱的一份是 <code>05-genlog</code></p><p>真实出片率只能当场记，事后一定记不准。<a href="/cases/case-06-kalshi-veo">案例 06</a> 之所以是整个知识库信息量最大的一篇，就是因为原作者当场记了废片数。</p></div><p>设计文档：<code>specs/2026-08-05-lab-module-design.md</code>。</p>',12)])])}const g=d(o,[["render",s]]);export{b as __pageData,g as default};
